package com.example.kymcoagility50.data.content

import kotlinx.serialization.Serializable

/**
 * Mirror of shared/content/agility50.json — the knowledge base shared with the website.
 * Generated by scripts/content/build_content.py; never edit the JSON by hand.
 */
@Serializable
data class Content(
    val schemaVersion: Int,
    val updated: String,
    val bike: BikeInfo,
    val quickSpecs: List<LabelValue>,
    val specs: List<SpecGroup>,
    val torque: List<List<String>>,
    val categories: List<Category>,
    val tasks: List<Task>,
    val milestones: List<Milestone>,
    val checklist: List<CheckItem>,
    val localTips: List<TitleText>,
    val troubleshooting: List<TroubleTree>,
    val failureModes: List<FailureMode>,
    val guides: List<Guide>,
    val seasons: List<Season>,
    val storage: List<String>,
    val oilStrategy: List<OilStep>,
    val warnings: List<TitleText>,
    val parts: List<List<String>>,
    val fixedCosts: List<List<String>>,
    val shops: List<Shop>,
    val emergency: List<EmergencyNumber>,
    val accidentSteps: List<String>,
    val documentTypes: List<DocumentType>,
    val gear: List<GearTier>,
    val docs: List<DocInfo>,
    val links: List<Link>,
    val resale: Resale
) {
    fun task(id: String): Task? = tasks.firstOrNull { it.id == id }
    fun guide(id: String): Guide? = guides.firstOrNull { it.id == id }
    fun category(id: String): Category? = categories.firstOrNull { it.id == id }
    fun documentType(id: String): DocumentType = documentTypes.firstOrNull { it.id == id } ?: documentTypes.last()
    fun seasonForMonth(month: Int): Season? = seasons.firstOrNull { month in it.months }
}

@Serializable data class BikeInfo(val model: String, val code: String, val tagline: String, val newPriceMad: Int, val city: String, val wiki: String)
@Serializable data class LabelValue(val label: String, val value: String)
@Serializable data class SpecGroup(val group: String, val rows: List<List<String>>)
@Serializable data class Category(val id: String, val name: String, val icon: String)

@Serializable
data class Task(
    val id: String,
    val cat: String,
    val name: String,
    val fr: String = "",
    val intervalKm: Int? = null,
    val intervalMonths: Int? = null,
    val intervalDays: Int? = null,
    val breakInKm: List<Int> = emptyList(),
    val label: String,
    val factory: String,
    val severity: String,
    val cost: String = "",
    val guide: String? = null,
    val notes: String = ""
)

@Serializable data class Milestone(val km: Int, val source: String, val title: String, val tasks: List<String>, val actions: String)
@Serializable data class CheckItem(val id: String, val group: String, val title: String, val detail: String)
@Serializable data class TitleText(val title: String, val text: String)

@Serializable
data class TroubleTree(val id: String, val title: String, val icon: String, val start: String, val nodes: Map<String, TroubleNode>)

@Serializable
data class TroubleNode(
    val q: String? = null,
    val options: List<List<String>> = emptyList(),
    val result: String? = null,
    val text: String? = null,
    val level: String? = null,
    val guide: String? = null
)

@Serializable data class FailureMode(val rank: Int, val name: String, val risk: Int, val level: String, val how: String, val detect: String, val prevent: String)

@Serializable
data class Guide(
    val id: String,
    val title: String,
    val interval: String,
    val time: String,
    val difficulty: String,
    val need: List<String>,
    val steps: List<List<String>>,
    val tips: List<List<String>>
)

@Serializable data class Season(val id: String, val name: String, val months: List<Int>, val range: String, val headline: String, val rows: List<List<String>>)
@Serializable data class OilStep(val period: String, val oil: String, val price: String, val interval: String)
@Serializable data class Shop(val name: String, val role: String, val note: String, val maps: String)
@Serializable data class EmergencyNumber(val label: String, val number: String, val note: String)
@Serializable data class DocumentType(val id: String, val label: String, val fr: String, val remindDays: Int, val hint: String)
@Serializable data class GearTier(val tier: String, val items: List<List<String>>)
@Serializable data class DocHighlight(val label: String, val page: Int)

@Serializable
data class DocInfo(
    val id: String,
    val title: String,
    val subtitle: String,
    val file: String,
    val index: String,
    val cover: String,
    val pages: Int,
    val highlights: List<DocHighlight>
)

@Serializable data class Link(val title: String, val url: String)
@Serializable data class Resale(val headline: String, val text: String, val targetKm: Int, val targetYears: Int)
